insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-001', 'enf', null, 'Segundo a Resolução COFEN nº 358/2009, o Processo de Enfermagem organiza-se em cinco etapas inter-relacionadas. São elas:', '["coleta de dados (histórico), diagnóstico, planejamento, implementação e avaliação de enfermagem.","admissão, triagem, prescrição médica, execução e alta.","anamnese, exame físico, prescrição médica, evolução e alta.","acolhimento, classificação de risco, encaminhamento, contrarreferência e alta.","diagnóstico, prescrição, dispensação, administração e registro."]'::jsonb, 0, 'COFEN 358/2009 (atualizada pela COFEN 736/2024, que manteve 5 etapas: avaliação, diagnóstico, planejamento, implementação e evolução de enfermagem).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-002', 'enf', null, 'De acordo com a Lei nº 7.498/1986 e a Resolução COFEN 358/2009, cabe privativamente ao enfermeiro:', '["o diagnóstico de enfermagem e a prescrição das ações ou intervenções de enfermagem.","a coleta de sinais vitais.","a anotação de enfermagem.","a administração de medicamentos por via oral.","a higiene do paciente acamado."]'::jsonb, 0, 'Técnicos e auxiliares participam do Processo de Enfermagem sob supervisão, mas diagnóstico e prescrição de enfermagem são privativos do enfermeiro.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-003', 'enf', null, 'Na taxonomia NANDA-I, um diagnóstico de enfermagem com foco no problema é composto, em regra, por:', '["título (rótulo), fatores relacionados e características definidoras.","nome da doença, CID e exames.","prescrição médica, dose e via.","metas, intervenções e alta.","sinais vitais e escala de dor."]'::jsonb, 0, 'Formato PES: problema (título), etiologia (fatores relacionados) e sinais/sintomas (características definidoras).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-004', 'enf', null, 'Segundo a Portaria nº 825/2016 (Atenção Domiciliar), a modalidade AD1 é de responsabilidade:', '["das equipes de atenção básica, para usuários estáveis que necessitam de cuidados de menor frequência.","exclusivamente do hospital de referência.","das EMAD e EMAP, para pacientes em ventilação mecânica.","do SAMU 192.","das operadoras de planos privados."]'::jsonb, 0, 'AD1: atenção básica. AD2 e AD3: Serviço de Atenção Domiciliar (EMAD com apoio da EMAP), para maior complexidade e frequência.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-005', 'enf', null, 'A Política Nacional de Atenção Integral à Saúde da Criança (PNAISC, Portaria nº 1.130/2015) considera criança a pessoa na faixa etária de:', '["0 a 9 anos.","0 a 5 anos.","0 a 12 anos incompletos.","0 a 18 anos.","1 a 10 anos."]'::jsonb, 0, 'PNAISC: criança de 0 a 9 anos (com atenção especial à primeira infância, de 0 a 5 anos).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-006', 'enf', null, 'Na abordagem da criança com diarreia e desidratação (sem sinais de gravidade), o Plano B de reidratação consiste em:', '["terapia de reidratação oral na unidade de saúde, com cerca de 50 a 100 mL/kg de SRO em 4 a 6 horas.","hidratação venosa imediata em todos os casos.","orientações para casa, sem uso de SRO.","jejum absoluto por 24 horas.","uso rotineiro de antidiarreico."]'::jsonb, 0, 'Plano A: sem desidratação (casa); Plano B: com desidratação (TRO na unidade); Plano C: desidratação grave (hidratação venosa).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-007', 'enf', null, 'Gestante com data da última menstruação (DUM) em 10/01/2026. Pela regra de Naegele, a data provável do parto é:', '["17/10/2026.","10/10/2026.","03/10/2026.","17/11/2026.","07/10/2026."]'::jsonb, 0, 'Naegele: DUM + 7 dias e − 3 meses (+1 ano quando aplicável): 10 + 7 = 17; janeiro − 3 = outubro → 17/10/2026.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-008', 'enf', null, 'Segundo o calendário do PNI, a vacina dTpa (tríplice bacteriana acelular do adulto) deve ser administrada na gestante:', '["a cada gestação, a partir da 20ª semana.","apenas na primeira gestação, no 1º trimestre.","somente no puerpério.","é contraindicada na gestação.","apenas se a gestante tiver mais de 35 anos."]'::jsonb, 0, 'dTpa a cada gestação, a partir da 20ª semana, para proteção do recém-nascido contra a coqueluche.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-009', 'enf', null, 'Gestante com sífilis latente tardia (ou de duração ignorada) deve ser tratada com:', '["penicilina benzatina 7.200.000 UI, em 3 doses semanais de 2.400.000 UI.","penicilina benzatina 2.400.000 UI em dose única.","azitromicina 1 g em dose única.","penicilina benzatina 1.200.000 UI em dose única.","tratamento apenas após o parto."]'::jsonb, 0, 'Sífilis recente (primária, secundária, latente recente): 2.400.000 UI dose única. Tardia ou ignorada: 3 doses semanais (total 7.200.000 UI). Só a penicilina trata o feto.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-010', 'enf', null, 'Segundo as Diretrizes Brasileiras para o Rastreamento do Câncer do Colo do Útero (INCA, 2016), o exame citopatológico deve ser:', '["iniciado aos 25 anos em quem já teve atividade sexual, até os 64 anos, a cada 3 anos após dois exames anuais consecutivos negativos.","iniciado aos 12 anos, anualmente, por toda a vida.","feito apenas após a menopausa.","feito a cada 6 meses a partir dos 18 anos.","contraindicado em gestantes."]'::jsonb, 0, 'Diretriz INCA 2016. Obs.: o MS vem implantando o teste DNA-HPV como rastreamento (intervalo de 5 anos), mas o edital costuma cobrar a diretriz citopatológica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-011', 'enf', null, 'A Lei Maria da Penha (Lei nº 11.340/2006) define como formas de violência doméstica e familiar contra a mulher, EXCETO:', '["institucional.","física.","psicológica.","patrimonial.","moral."]'::jsonb, 0, 'Art. 7º: física, psicológica, sexual, patrimonial e moral.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-012', 'enf', null, 'Quanto à notificação de violência contra a mulher atendida em serviço de saúde, é correto afirmar:', '["é compulsória em serviços de saúde públicos e privados.","é facultativa, a critério da paciente.","só ocorre com boletim de ocorrência prévio.","é obrigatória apenas em hospitais públicos.","é vedada, por quebra de sigilo."]'::jsonb, 0, 'Lei 10.778/2003: notificação compulsória em todo o território nacional, em serviços públicos e privados. A violência sexual é de notificação imediata ao município.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-013', 'enf', null, 'A Política Nacional de Atenção Integral à Saúde do Homem (PNAISH) tem como população-alvo prioritária os homens na faixa etária de:', '["20 a 59 anos.","12 a 18 anos.","60 anos ou mais.","0 a 9 anos.","40 a 79 anos."]'::jsonb, 0, 'PNAISH (Portaria 1.944/2009): 20 a 59 anos; eixos incluem acesso e acolhimento, saúde sexual e reprodutiva, paternidade e cuidado (pré-natal do parceiro), doenças prevalentes e prevenção de violências e acidentes.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-014', 'enf', null, 'O Estatuto da Pessoa Idosa (Lei nº 10.741/2003) assegura à pessoa idosa internada ou em observação:', '["o direito a acompanhante, devendo o órgão de saúde proporcionar condições adequadas para sua permanência em tempo integral.","acompanhante apenas no período diurno.","acompanhante somente para maiores de 80 anos.","acompanhante mediante pagamento de diária.","visitas apenas aos finais de semana."]'::jsonb, 0, 'Art. 16 do Estatuto. Pessoa idosa: 60 anos ou mais; prioridade especial para maiores de 80 anos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-015', 'enf', null, 'Na avaliação multidimensional da pessoa idosa, a escala de Katz avalia:', '["as atividades básicas de vida diária (banho, vestir-se, uso do banheiro, transferência, continência e alimentação).","as atividades instrumentais (uso do telefone, finanças, compras).","a cognição.","o risco de queda.","a depressão geriátrica."]'::jsonb, 0, 'Katz = ABVD; Lawton = AIVD; Mini-Exame do Estado Mental = cognição; Escala de Depressão Geriátrica (GDS) = depressão.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-016', 'enf', null, 'Na Rede de Atenção Psicossocial (Portaria nº 3.088/2011), o CAPS III caracteriza-se por:', '["funcionar 24 horas, inclusive feriados e fins de semana, com acolhimento noturno.","atender exclusivamente crianças e adolescentes.","funcionar apenas em horário comercial.","ser serviço de internação de longa permanência.","atender somente casos leves."]'::jsonb, 0, 'CAPS III e CAPS AD III oferecem atenção contínua 24 h, com leitos de acolhimento noturno.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-017', 'enf', null, 'Segundo a Lei nº 8.213/1991, o acidente sofrido pelo trabalhador no percurso da residência para o local de trabalho:', '["equipara-se ao acidente do trabalho (acidente de trajeto).","não tem relação com o trabalho.","só é considerado se houver óbito.","dispensa a Comunicação de Acidente de Trabalho em qualquer caso.","é responsabilidade exclusiva do trabalhador."]'::jsonb, 0, 'O acidente de trajeto é equiparado ao acidente de trabalho; a emissão da CAT é obrigatória.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-018', 'enf', null, 'O Centro de Referência em Saúde do Trabalhador (CEREST) integra a:', '["Rede Nacional de Atenção Integral à Saúde do Trabalhador (RENAST).","Rede de Atenção Psicossocial (RAPS).","Rede Cegonha.","Rede de Urgência e Emergência.","Agência Nacional de Saúde Suplementar."]'::jsonb, 0, 'O CEREST dá suporte técnico e é polo irradiador das ações de saúde do trabalhador no território (RENAST).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-019', 'enf', null, 'É agravo de notificação compulsória IMEDIATA (até 24 horas):', '["sarampo.","hanseníase.","tuberculose.","hepatite B crônica.","sífilis adquirida."]'::jsonb, 0, 'Sarampo, raiva humana, botulismo, cólera, entre outros, são imediatos. Hanseníase, tuberculose, hepatites e sífilis adquirida são de notificação semanal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-020', 'enf', null, 'Em epidemiologia, a incidência de uma doença corresponde:', '["ao número de casos novos em uma população exposta durante determinado período.","ao total de casos existentes (novos e antigos) em um momento.","ao número de óbitos pela doença.","à proporção de curados.","ao número de pessoas vacinadas."]'::jsonb, 0, 'Incidência = casos novos/população em risco no período (mede risco). Prevalência = casos existentes (novos + antigos).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-021', 'enf', null, 'O coeficiente de mortalidade infantil é calculado pela razão entre:', '["óbitos de menores de 1 ano e o número de nascidos vivos, no mesmo local e período, multiplicada por 1.000.","óbitos de menores de 5 anos e a população total, multiplicada por 100.","óbitos fetais e o total de gestações.","óbitos de menores de 1 ano e a população total, multiplicada por 100.000.","nascidos vivos e óbitos maternos."]'::jsonb, 0, 'CMI = (óbitos < 1 ano / nascidos vivos) × 1.000.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-022', 'enf', null, 'A sensibilidade de um teste diagnóstico é a capacidade de:', '["identificar corretamente os indivíduos doentes (verdadeiros positivos).","identificar corretamente os indivíduos sadios (verdadeiros negativos).","produzir resultados iguais em repetições.","reduzir o custo do exame.","detectar apenas casos graves."]'::jsonb, 0, 'Sensibilidade = VP/(VP+FN). Especificidade = VN/(VN+FP), capacidade de identificar os sadios.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-023', 'enf', null, 'O VIGITEL, utilizado na vigilância das Doenças e Agravos Não Transmissíveis (DANT), é:', '["um inquérito telefônico de vigilância de fatores de risco e proteção para doenças crônicas.","um sistema de notificação de doenças transmissíveis.","o sistema de informação sobre nascidos vivos.","um programa de vacinação.","um sistema de regulação de leitos."]'::jsonb, 0, 'VIGITEL monitora tabagismo, consumo de álcool, alimentação, atividade física, excesso de peso etc. nas capitais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-024', 'enf', null, 'Segundo a Sociedade Brasileira de Diabetes, é critério diagnóstico de diabetes mellitus (confirmado em segunda amostra):', '["glicemia de jejum ≥ 126 mg/dL.","glicemia de jejum entre 100 e 125 mg/dL.","HbA1c de 5,7%.","glicemia 2 h após TOTG de 150 mg/dL.","glicemia casual de 140 mg/dL sem sintomas."]'::jsonb, 0, 'DM: jejum ≥ 126; TOTG 2 h ≥ 200; HbA1c ≥ 6,5%; glicemia casual ≥ 200 com sintomas. Jejum 100–125 = pré-diabetes.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-025', 'enf', null, 'Durante a gestação, é contraindicada, em regra, a vacina:', '["tríplice viral (sarampo, caxumba e rubéola).","hepatite B.","dT (dupla adulto).","dTpa.","influenza."]'::jsonb, 0, 'Vacinas de vírus vivos atenuados (tríplice viral, varicela) são contraindicadas na gestação. Febre amarela só em situações de risco epidemiológico avaliado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-026', 'enf', null, 'No calendário do PNI atualizado em 2024, a vacina HPV quadrivalente para meninas e meninos de 9 a 14 anos passou a ser administrada em:', '["dose única.","duas doses com intervalo de 6 meses.","três doses (0, 2 e 6 meses).","dose anual.","reforço a cada 10 anos."]'::jsonb, 0, 'Desde 2024 o MS adota esquema de dose única para 9 a 14 anos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-027', 'enf', null, 'Segundo a Lei nº 8.080/1990, o "conjunto de ações capaz de eliminar, diminuir ou prevenir riscos à saúde e de intervir nos problemas sanitários decorrentes do meio ambiente, da produção e circulação de bens e da prestação de serviços de interesse da saúde" é a definição de:', '["vigilância sanitária.","vigilância epidemiológica.","saúde do trabalhador.","atenção básica.","assistência farmacêutica."]'::jsonb, 0, 'Art. 6º, §1º, da Lei 8.080/90.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-028', 'enf', null, 'A Agência Nacional de Vigilância Sanitária (ANVISA) foi criada pela:', '["Lei nº 9.782/1999.","Lei nº 8.080/1990.","Lei nº 8.142/1990.","Lei nº 10.216/2001.","Lei nº 9.656/1998."]'::jsonb, 0, 'A Lei 9.782/1999 definiu o Sistema Nacional de Vigilância Sanitária e criou a ANVISA. A Lei 9.656/98 trata dos planos de saúde.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-029', 'enf', null, 'Na PCR em assistolia ou atividade elétrica sem pulso, o fármaco indicado e sua dose são:', '["adrenalina 1 mg EV/IO a cada 3 a 5 minutos.","amiodarona 300 mg em bolus.","atropina 3 mg em dose única.","adenosina 6 mg em bolus rápido.","lidocaína 5 mg/kg."]'::jsonb, 0, 'Ritmos não chocáveis: RCP + adrenalina o mais precoce possível, a cada 3–5 min, e busca de causas reversíveis (5 Hs e 5 Ts).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-030', 'enf', null, 'Na FV/TV sem pulso refratária ao choque, a dose inicial de amiodarona é de:', '["300 mg EV/IO em bolus, podendo-se repetir 150 mg.","150 mg em infusão de 24 h.","1 mg a cada 3 minutos.","50 mg IM.","5 mg/kg VO."]'::jsonb, 0, 'Amiodarona: 1ª dose 300 mg; 2ª dose 150 mg (alternativa: lidocaína).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-031', 'enf', null, 'No Protocolo de Manchester, a cor amarela corresponde a:', '["urgente, com tempo-alvo de atendimento de até 60 minutos.","emergência, com atendimento imediato.","muito urgente, em até 10 minutos.","pouco urgente, em até 120 minutos.","não urgente, em até 240 minutos."]'::jsonb, 0, 'Vermelho: imediato; laranja: 10 min; amarelo: 60 min; verde: 120 min; azul: 240 min.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-032', 'enf', null, 'No AVC isquêmico agudo, a trombólise endovenosa com alteplase pode ser realizada, respeitados os critérios, até:', '["4,5 horas do início dos sintomas.","24 horas do início dos sintomas.","30 minutos do início dos sintomas.","72 horas do início dos sintomas.","12 horas do início dos sintomas."]'::jsonb, 0, 'A janela clássica para trombólise EV é de até 4,5 h. A Escala de Cincinnati avalia face, braço e fala.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-033', 'enf', null, 'No infarto agudo do miocárdio com supradesnivelamento do segmento ST, as metas de tempo recomendadas são:', '["porta-agulha ≤ 30 minutos e porta-balão ≤ 90 minutos.","porta-agulha ≤ 6 horas.","porta-balão ≤ 24 horas.","porta-ECG ≤ 60 minutos.","não há tempo recomendado."]'::jsonb, 0, 'ECG em até 10 minutos da chegada; fibrinólise em até 30 min; angioplastia primária em até 90 min.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-034', 'enf', null, 'Na UTI, a escala RASS (Richmond Agitation-Sedation Scale) é utilizada para avaliar:', '["o nível de sedação e agitação, de −5 (não desperta) a +4 (combativo).","o risco de lesão por pressão.","a dor em pacientes comunicativos.","o risco nutricional.","a gravidade da sepse."]'::jsonb, 0, 'RASS 0 = alerta e calmo. Meta habitual de sedação leve: 0 a −2.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-035', 'enf', null, 'Entre as medidas do bundle de prevenção da pneumonia associada à ventilação mecânica, destaca-se:', '["manter a cabeceira elevada entre 30° e 45°.","manter o paciente em decúbito zero.","trocar o circuito do ventilador diariamente.","manter sedação profunda contínua sem interrupção.","desinsuflar o cuff periodicamente."]'::jsonb, 0, 'Bundle: cabeceira 30–45°, interrupção diária da sedação, avaliação de extubação, higiene oral, pressão do cuff adequada (20–30 cmH2O).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-036', 'enf', null, 'Segundo a RDC nº 15/2012 (ANVISA), o fluxo de processamento de produtos para saúde no CME deve ser:', '["unidirecional, da área suja para a área limpa, sem cruzamento.","bidirecional, para agilizar o trabalho.","aleatório, conforme a demanda.","da área limpa para a suja.","centralizado na sala de expurgo."]'::jsonb, 0, 'O fluxo unidirecional (expurgo → preparo → esterilização → armazenamento) evita contaminação cruzada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-037', 'enf', null, 'O teste de Bowie-Dick, em autoclaves com pré-vácuo, tem como finalidade:', '["avaliar a eficácia da remoção de ar da câmara, devendo ser realizado diariamente, antes do primeiro ciclo.","verificar a presença de esporos vivos.","medir a umidade das embalagens.","testar a temperatura da sala.","substituir o indicador biológico."]'::jsonb, 0, 'Bowie-Dick (indicador químico classe 2) detecta falhas na remoção do ar e penetração do vapor.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-038', 'enf', null, 'Segundo a Portaria MS nº 2.616/1998, quando se desconhece o período de incubação do microrganismo, é considerada infecção hospitalar aquela que se manifesta:', '["após 72 horas da admissão.","nas primeiras 24 horas de internação.","somente após a alta.","apenas em pacientes cirúrgicos.","antes da admissão."]'::jsonb, 0, 'Também são hospitalares as infecções manifestadas antes de 72 h quando associadas a procedimentos realizados durante a internação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-039', 'enf', null, 'No bundle de inserção do cateter venoso central para prevenção de infecção de corrente sanguínea, recomenda-se:', '["higiene das mãos, barreira máxima de precaução e antissepsia da pele com clorexidina alcoólica.","preferir a veia femoral em adultos.","usar apenas luvas de procedimento.","antissepsia com álcool 70% sem esperar secar.","trocar o cateter rotineiramente a cada 72 h."]'::jsonb, 0, 'Inclui também a preferência pela subclávia em adultos e a revisão diária da necessidade do cateter.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-040', 'enf', null, 'Para paciente internado com varicela, as precauções indicadas são:', '["aerossóis e contato.","gotículas apenas.","apenas precaução padrão.","contato apenas.","isolamento reverso."]'::jsonb, 0, 'Varicela e herpes-zóster disseminado: aerossóis + contato até todas as lesões virarem crostas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-041', 'enf', null, 'São exemplos de medicamentos potencialmente perigosos (de alta vigilância), que exigem dupla checagem:', '["cloreto de potássio concentrado, insulina e heparina.","dipirona oral e paracetamol.","soro fisiológico 0,9% de 100 mL.","vitamina C e complexo B.","hidratante cutâneo."]'::jsonb, 0, 'Lista ISMP: eletrólitos concentrados (KCl), insulinas, anticoagulantes, opioides, quimioterápicos, entre outros.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-042', 'enf', null, 'Prescrição: heparina 2.500 UI por via subcutânea. Disponível: frasco de 5.000 UI/mL. Deve-se administrar:', '["0,5 mL.","0,25 mL.","1 mL.","2 mL.","5 mL."]'::jsonb, 0, '5.000 UI — 1 mL; 2.500 UI — x → x = 0,5 mL.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-043', 'enf', null, 'Foram prescritos 500 mL de SF 0,9% para correr em 4 horas, com equipo macrogotas. O gotejamento correto é de aproximadamente:', '["42 gotas/min.","21 gotas/min.","63 gotas/min.","125 gotas/min.","31 gotas/min."]'::jsonb, 0, 'Gotas/min = V ÷ (T × 3) = 500 ÷ 12 ≈ 41,7 ≈ 42 gotas/min.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-044', 'enf', null, 'Uma ampola de 10 mL de cloreto de potássio a 19,1% contém aproximadamente:', '["25 mEq de potássio.","10 mEq de potássio.","1 mEq de potássio.","19,1 mEq de potássio.","50 mEq de potássio."]'::jsonb, 0, 'KCl 19,1% = 1,91 g em 10 mL ≈ 2,5 mEq/mL → cerca de 25 mEq por ampola. Nunca administrar em bolus; sempre diluído.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-045', 'enf', null, 'O curativo de alginato de cálcio está indicado principalmente em feridas:', '["com exsudato moderado a abundante, inclusive com sangramento leve.","secas, com necrose seca e sem exsudato.","com exposição óssea, sem exsudato.","de queimadura de 1º grau.","apenas em pele íntegra."]'::jsonb, 0, 'O alginato absorve exsudato formando gel e tem ação hemostática. Feridas secas: hidrogel (desbridamento autolítico).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-046', 'enf', null, 'Em comparação com a colostomia, a ileostomia apresenta efluente:', '["líquido a pastoso, com enzimas digestivas, mais agressivo à pele periestoma.","sempre sólido e formado.","sem risco para a pele.","exclusivamente urinário.","inexistente nos primeiros 30 dias."]'::jsonb, 0, 'Quanto mais proximal o estoma no intestino, mais líquido e irritativo é o efluente; risco de desidratação e dermatite.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-047', 'enf', null, 'Pela Lei nº 9.263/1996, alterada pela Lei nº 14.443/2022, a esterilização voluntária (laqueadura/vasectomia) é permitida em pessoas com capacidade civil plena e:', '["maiores de 21 anos ou com pelo menos dois filhos vivos, observado o prazo mínimo de 60 dias entre a manifestação da vontade e o procedimento.","maiores de 25 anos, com consentimento obrigatório do cônjuge.","maiores de 18 anos, sem prazo.","somente após três filhos vivos.","apenas durante o parto, em qualquer idade."]'::jsonb, 0, 'A Lei 14.443/2022 reduziu a idade para 21 anos, dispensou o consentimento do cônjuge e permitiu a laqueadura no parto (respeitado o prazo de 60 dias).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-048', 'enf', null, 'Na hanseníase, para fins de tratamento, o caso é classificado como multibacilar quando apresenta:', '["mais de 5 lesões de pele.","até 5 lesões de pele.","uma lesão única sem alteração de sensibilidade.","apenas baciloscopia negativa.","ausência de lesões."]'::jsonb, 0, 'Paucibacilar: até 5 lesões (PQT-U 6 doses). Multibacilar: mais de 5 lesões ou baciloscopia positiva (PQT-U 12 doses).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-049', 'enf', null, 'Na pré-eclâmpsia grave, o fármaco de escolha para prevenção e tratamento da eclâmpsia é o:', '["sulfato de magnésio, tendo como antídoto o gluconato de cálcio.","diazepam, tendo como antídoto o flumazenil.","ocitocina.","fenitoína, tendo como antídoto a naloxona.","furosemida."]'::jsonb, 0, 'Sinais de intoxicação por magnésio: abolição do reflexo patelar, FR < 12–16 irpm e diurese < 25 mL/h.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-050', 'enf', null, 'Para prevenção da hemorragia pós-parto, recomenda-se no terceiro período do parto (após o nascimento):', '["ocitocina 10 UI por via intramuscular.","metilergometrina em todas as hipertensas.","misoprostol por via oral a todas, sem avaliação.","ácido acetilsalicílico.","massagem uterina apenas após 24 h."]'::jsonb, 0, 'A ocitocina 10 UI IM logo após o nascimento é a principal medida de manejo ativo do 3º período. Metilergometrina é contraindicada em hipertensas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-051', 'enf', null, 'Atualmente, a Resolução COFEN que dispõe sobre a implementação do Processo de Enfermagem em todo contexto socioambiental onde ocorre o cuidado de enfermagem, revogando a Resolução COFEN nº 358/2009, é a:', '["Resolução COFEN nº 736/2024.","Resolução COFEN nº 564/2017.","Resolução COFEN nº 543/2017.","Resolução COFEN nº 427/2012.","Resolução COFEN nº 311/2007."]'::jsonb, 0, 'A 736/2024 organiza o PE em cinco etapas: avaliação, diagnóstico, planejamento, implementação e evolução de enfermagem.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-052', 'enf', null, 'Segundo a Lei nº 7.498/1986, cabe ao enfermeiro, como integrante da equipe de saúde:', '["a prescrição de medicamentos estabelecidos em programas de saúde pública e em rotina aprovada pela instituição de saúde.","a prescrição de qualquer medicamento, sem restrição.","a realização de cirurgias de médio porte.","o diagnóstico nosológico de doenças.","a emissão de atestado de óbito."]'::jsonb, 0, 'Art. 11, II, c. A prescrição de enfermagem está vinculada a programas e protocolos institucionais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-053', 'enf', null, 'Segundo a Lei nº 7.498/1986, à enfermeira obstétrica e à obstetriz incumbe, além das atividades do enfermeiro:', '["a realização de episiotomia e episiorrafia e a aplicação de anestesia local, quando necessária.","a realização de cesariana.","a indicação de histerectomia.","o uso de fórceps de alívio.","a prescrição de qualquer medicamento à gestante."]'::jsonb, 0, 'Art. 11, parágrafo único. Também cabe a assistência ao parto sem distocia e a identificação de distocias até a chegada do médico.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-054', 'enf', null, 'A teoria de enfermagem desenvolvida por Wanda de Aguiar Horta, base de muitos modelos de SAE no Brasil, é a das:', '["Necessidades Humanas Básicas.","Relações Interpessoais.","Déficit de Autocuidado.","Adaptação.","Transições."]'::jsonb, 0, 'Horta baseou-se na hierarquia de necessidades de Maslow (necessidades psicobiológicas, psicossociais e psicoespirituais).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-055', 'enf', null, 'A teoria de enfermagem centrada na capacidade do indivíduo de realizar ações em benefício próprio, com sistemas totalmente compensatórios, parcialmente compensatórios e de apoio-educação, é de:', '["Dorothea Orem.","Hildegard Peplau.","Florence Nightingale.","Callista Roy.","Wanda Horta."]'::jsonb, 0, 'Teoria do Déficit de Autocuidado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-056', 'enf', null, 'Hildegard Peplau é conhecida pela teoria que enfatiza:', '["as relações interpessoais entre enfermeiro e paciente.","o ambiente como fator central da saúde.","o autocuidado.","a adaptação a estímulos.","o cuidado transcultural."]'::jsonb, 0, 'Fases: orientação, identificação, exploração e resolução.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-057', 'enf', null, 'Na NANDA-I, um diagnóstico de enfermagem de risco é composto por:', '["título e fatores de risco, sem características definidoras.","título, fatores relacionados e características definidoras.","apenas características definidoras.","nome da doença e sintomas.","título e intervenções."]'::jsonb, 0, 'Como o problema ainda não ocorreu, não há sinais/sintomas (características definidoras).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-058', 'enf', null, 'A classificação padronizada que descreve os resultados de enfermagem sensíveis às intervenções é a:', '["NOC.","NIC.","NANDA-I.","CID-10.","CIAP-2."]'::jsonb, 0, 'NIC = intervenções; NOC = resultados; NANDA-I = diagnósticos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-059', 'enf', null, 'Segundo a Resolução COFEN nº 543/2017, as horas de enfermagem por paciente em cuidado intensivo, nas 24 horas, são:', '["18 horas.","4 horas.","6 horas.","10 horas.","24 horas."]'::jsonb, 0, 'Mínimo: 4 h; intermediário: 6 h; alta dependência: 10 h; semi-intensivo: 10 h; intensivo: 18 h.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-060', 'enf', null, 'Segundo a Resolução COFEN nº 543/2017, para pacientes em cuidado intensivo, o percentual mínimo de enfermeiros no quadro de enfermagem é de:', '["52%.","33%.","36%.","42%.","100%."]'::jsonb, 0, 'Mínimo e intermediário: 33%; alta dependência: 36%; semi-intensivo: 42%; intensivo: 52%.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-061', 'enf', null, 'O Sistema de Classificação de Pacientes de Fugulin é utilizado para:', '["classificar os pacientes segundo o grau de dependência da equipe de enfermagem, subsidiando o dimensionamento de pessoal.","avaliar o risco de lesão por pressão.","classificar o risco na porta de urgência.","estadiar o câncer.","medir o nível de consciência."]'::jsonb, 0, 'Categorias: cuidados mínimos, intermediários, alta dependência, semi-intensivos e intensivos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-062', 'enf', null, 'Quanto aos registros de enfermagem, é atividade privativa do enfermeiro:', '["a evolução de enfermagem.","a anotação de sinais vitais.","o registro de medicamentos administrados.","a anotação de intercorrências.","o registro do balanço hídrico."]'::jsonb, 0, 'A evolução é a análise reflexiva do enfermeiro sobre a resposta do paciente; a anotação é feita por toda a equipe.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-063', 'enf', null, 'O ciclo PDCA, ferramenta de gestão da qualidade, compreende as etapas:', '["planejar, executar, verificar e agir.","prever, decidir, controlar e avaliar.","planejar, dirigir, coordenar e arquivar.","pesquisar, divulgar, comprar e armazenar.","priorizar, delegar, cobrar e avaliar."]'::jsonb, 0, 'Plan, Do, Check, Act: ciclo contínuo de melhoria.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-064', 'enf', null, 'O diagrama de Ishikawa (espinha de peixe) é uma ferramenta de qualidade utilizada para:', '["identificar e organizar as possíveis causas de um problema.","calcular o dimensionamento de pessoal.","classificar o risco de pacientes.","medir a satisfação do usuário.","elaborar a escala mensal."]'::jsonb, 0, 'Agrupa causas em categorias (método, máquina, material, mão de obra, meio ambiente, medida).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-065', 'enf', null, 'Segundo a Portaria nº 825/2016, um usuário em ventilação mecânica no domicílio deve ser acompanhado na modalidade:', '["AD3.","AD1.","AD2.","atenção básica exclusivamente.","não pode ser atendido em domicílio."]'::jsonb, 0, 'AD3: necessidade de cuidado mais frequente, uso de equipamentos ou procedimentos de maior complexidade.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-066', 'enf', null, 'No Serviço de Atenção Domiciliar, a Equipe Multiprofissional de Apoio (EMAP) deve ter composição mínima de:', '["três profissionais de nível superior, escolhidos entre categorias como assistente social, fisioterapeuta, fonoaudiólogo, nutricionista, psicólogo, farmacêutico, odontólogo e terapeuta ocupacional.","um médico e um técnico de enfermagem.","dois enfermeiros.","um agente comunitário de saúde.","cinco médicos especialistas."]'::jsonb, 0, 'A EMAP apoia a EMAD (que tem médico, enfermeiro, fisioterapeuta ou assistente social e técnicos de enfermagem).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-067', 'enf', null, 'Para a inclusão de usuário com dependência funcional no Serviço de Atenção Domiciliar, é necessária:', '["a presença de cuidador identificado.","a contratação de enfermeiro particular.","a existência de plano de saúde.","a autorização judicial.","a internação prévia em UTI."]'::jsonb, 0, 'O cuidador é parte essencial do plano de cuidados no domicílio.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-068', 'enf', null, 'Segundo o Ministério da Saúde, o calendário mínimo de consultas de puericultura no primeiro ano de vida prevê consultas:', '["na 1ª semana e no 1º, 2º, 4º, 6º, 9º e 12º meses.","apenas aos 6 e 12 meses.","mensais durante todo o ano, totalizando 12.","somente quando a criança adoecer.","no 3º, 6º e 9º meses."]'::jsonb, 0, 'São 7 consultas no 1º ano, e mais 2 no 2º ano (18 e 24 meses).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-069', 'enf', null, 'A fontanela anterior (bregmática) costuma fechar entre:', '["9 e 18 meses.","1 e 2 meses.","3 e 4 anos.","o nascimento e 15 dias.","5 e 6 anos."]'::jsonb, 0, 'A posterior fecha por volta dos 2 meses. Fontanela abaulada pode indicar hipertensão intracraniana; deprimida, desidratação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-070', 'enf', null, 'O reflexo de Moro, presente no recém-nascido, normalmente desaparece por volta dos:', '["4 a 6 meses.","15 dias.","12 meses.","2 anos.","5 anos."]'::jsonb, 0, 'A persistência além do esperado pode indicar alteração neurológica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-071', 'enf', null, 'Na estratégia AIDPI, são sinais gerais de perigo na criança de 2 meses a 5 anos:', '["não conseguir beber ou mamar, vomitar tudo o que ingere, ter convulsões e estar letárgica ou inconsciente.","febre baixa e coriza.","tosse há 2 dias sem febre.","diarreia sem desidratação.","apetite aumentado."]'::jsonb, 0, 'Qualquer sinal geral de perigo indica referência urgente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-072', 'enf', null, 'Segundo a AIDPI, considera-se respiração rápida em criança de 12 meses a 5 anos a frequência respiratória de:', '["40 irpm ou mais.","20 irpm ou mais.","30 irpm ou mais.","60 irpm ou mais.","70 irpm ou mais."]'::jsonb, 0, '< 2 meses: ≥ 60; 2 a 11 meses: ≥ 50; 12 meses a 5 anos: ≥ 40.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-073', 'enf', null, 'O Programa Nacional de Suplementação de Ferro prevê a suplementação profilática para crianças na faixa etária de:', '["6 a 24 meses.","0 a 3 meses.","2 a 5 anos.","5 a 10 anos.","apenas recém-nascidos prematuros."]'::jsonb, 0, 'A anemia ferropriva é a carência nutricional mais comum na infância.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-074', 'enf', null, 'Na introdução da alimentação complementar, a partir dos 6 meses, é contraindicado oferecer à criança menor de 1 ano:', '["mel, pelo risco de botulismo.","frutas amassadas.","legumes cozidos.","carnes bem cozidas.","feijão amassado."]'::jsonb, 0, 'Também devem ser evitados açúcar, ultraprocessados e sal em excesso.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-075', 'enf', null, 'O teste do reflexo vermelho (teste do olhinho) tem como objetivo detectar precocemente:', '["alterações que comprometem a transparência dos meios oculares, como catarata congênita, glaucoma e retinoblastoma.","surdez congênita.","cardiopatias congênitas.","fenilcetonúria.","anquiloglossia."]'::jsonb, 0, 'Deve ser feito antes da alta da maternidade e repetido nas consultas de puericultura.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-076', 'enf', null, 'O componente neonatal precoce da mortalidade infantil corresponde aos óbitos ocorridos:', '["de 0 a 6 dias de vida.","de 7 a 27 dias de vida.","de 28 a 364 dias de vida.","de 1 a 4 anos.","durante a gestação."]'::jsonb, 0, 'Neonatal tardio: 7 a 27 dias; pós-neonatal: 28 a 364 dias.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-077', 'enf', null, 'O Marco Legal da Primeira Infância (Lei nº 13.257/2016) considera primeira infância o período que abrange:', '["os primeiros 6 anos completos ou 72 meses de vida.","os primeiros 2 anos de vida.","do nascimento aos 12 anos.","dos 6 aos 10 anos.","a gestação apenas."]'::jsonb, 0, 'A PNAISC também dá atenção especial a esse período.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-078', 'enf', null, 'Segundo o Estatuto da Criança e do Adolescente, os casos de suspeita ou confirmação de maus-tratos contra criança ou adolescente:', '["serão obrigatoriamente comunicados ao Conselho Tutelar da respectiva localidade.","só podem ser comunicados com autorização dos pais.","devem ser mantidos em sigilo absoluto pela equipe.","devem ser comunicados apenas se houver lesão grave.","são comunicados exclusivamente à escola."]'::jsonb, 0, 'Art. 13 do ECA, sem prejuízo de outras providências legais e da notificação ao SINAN.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-079', 'enf', null, 'Segundo o Ministério da Saúde, em uma gestação de risco habitual, as consultas de pré-natal devem ser:', '["mensais até a 28ª semana, quinzenais da 28ª à 36ª e semanais da 36ª até a 41ª semana.","trimestrais durante toda a gestação.","semanais desde o início.","apenas no 1º e no 3º trimestres.","mensais até o parto, sem alteração."]'::jsonb, 0, 'Não existe alta do pré-natal antes do parto.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-080', 'enf', null, 'Na medida da altura uterina, o fundo do útero costuma atingir a cicatriz umbilical por volta da:', '["20ª semana de gestação.","12ª semana de gestação.","16ª semana de gestação.","28ª semana de gestação.","36ª semana de gestação."]'::jsonb, 0, 'Com 12 semanas, o útero está próximo à sínfise púbica; com 16, entre a sínfise e a cicatriz umbilical.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-081', 'enf', null, 'A frequência normal dos batimentos cardíacos fetais é de:', '["110 a 160 bpm.","60 a 100 bpm.","80 a 110 bpm.","160 a 200 bpm.","200 a 240 bpm."]'::jsonb, 0, 'Valores persistentes fora dessa faixa exigem avaliação imediata.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-082', 'enf', null, 'As manobras de Leopold, realizadas na palpação obstétrica, permitem identificar:', '["a situação, a apresentação e a posição fetal.","a dilatação do colo uterino.","a frequência cardíaca fetal.","a pressão arterial materna.","a idade gestacional exata."]'::jsonb, 0, 'São quatro tempos de palpação abdominal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-083', 'enf', null, 'Segundo o consenso brasileiro adotado pelo Ministério da Saúde, uma glicemia de jejum entre 92 e 125 mg/dL na gestação indica:', '["diabetes mellitus gestacional.","diabetes mellitus prévio à gestação.","glicemia normal.","hipoglicemia.","necessidade imediata de interrupção da gestação."]'::jsonb, 0, 'Glicemia de jejum ≥ 126 mg/dL indica diabetes diagnosticado na gestação (overt diabetes).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-084', 'enf', null, 'O teste oral de tolerância à glicose (TOTG 75 g) para rastreamento do diabetes gestacional, em gestantes com glicemia de jejum normal, é indicado entre:', '["24 e 28 semanas.","6 e 8 semanas.","12 e 14 semanas.","36 e 40 semanas.","no puerpério imediato."]'::jsonb, 0, 'Valores alterados: jejum ≥ 92, 1 h ≥ 180 ou 2 h ≥ 153 mg/dL.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-085', 'enf', null, 'A suplementação de ácido fólico no período periconcepcional e no início da gestação tem como principal finalidade:', '["prevenir defeitos do tubo neural.","prevenir diabetes gestacional.","tratar infecção urinária.","prevenir pré-eclâmpsia.","aumentar o peso fetal."]'::jsonb, 0, 'Idealmente iniciada pelo menos 30 dias antes da concepção.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-086', 'enf', null, 'Para fins de vigilância da sífilis congênita, considera-se tratamento adequado da gestante aquele realizado com:', '["penicilina benzatina, iniciado até 30 dias antes do parto, com esquema completo de acordo com o estágio clínico.","azitromicina em dose única.","qualquer antibiótico, em qualquer momento da gestação.","penicilina benzatina iniciada no dia do parto.","ceftriaxona por 3 dias."]'::jsonb, 0, 'Fora desses critérios, o RN é considerado exposto a tratamento inadequado e investigado como caso.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-087', 'enf', null, 'Para o recém-nascido exposto ao HIV, as recomendações incluem:', '["iniciar a profilaxia antirretroviral preferencialmente nas primeiras 4 horas de vida e não amamentar.","estimular o aleitamento materno exclusivo.","iniciar a profilaxia apenas após 30 dias.","permitir o aleitamento cruzado.","dispensar acompanhamento se a mãe estiver em tratamento."]'::jsonb, 0, 'No Brasil, a amamentação é contraindicada; a criança recebe fórmula láctea.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-088', 'enf', null, 'No acompanhamento puerperal, o Ministério da Saúde recomenda:', '["visita/consulta na primeira semana após o parto e consulta puerperal até 42 dias.","consulta apenas após 6 meses.","nenhuma consulta, se o parto foi normal.","consulta somente se houver febre.","consulta apenas para o recém-nascido."]'::jsonb, 0, 'A primeira semana é estratégica para avaliar mãe e bebê, aleitamento e sinais de risco.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-089', 'enf', null, 'Pelos critérios de elegibilidade da OMS, o anticoncepcional oral combinado é contraindicado para mulheres:', '["com 35 anos ou mais que fumam 15 ou mais cigarros por dia.","com menos de 20 anos.","que nunca tiveram filhos.","com ciclos menstruais irregulares.","que desejam engravidar no futuro."]'::jsonb, 0, 'O risco cardiovascular (trombose, AVC, IAM) é elevado nessa combinação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-090', 'enf', null, 'A anticoncepção de emergência com levonorgestrel:', '["pode ser usada até 5 dias após a relação desprotegida, sendo mais eficaz quanto mais cedo for tomada.","é abortiva.","só funciona se tomada antes da relação.","deve ser usada como método regular.","protege contra IST."]'::jsonb, 0, 'Ela atua principalmente impedindo ou retardando a ovulação; não interrompe gravidez já implantada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-091', 'enf', null, 'São sinais e sintomas suspeitos de câncer de mama que exigem investigação:', '["nódulo endurecido e fixo, retração de pele ou mamilo, descarga papilar sanguinolenta e pele em casca de laranja.","dor mamária cíclica no período pré-menstrual.","mamas simétricas e indolores.","aumento discreto das mamas na gestação.","colostro no fim da gestação."]'::jsonb, 0, 'Esses sinais devem ser avaliados em qualquer idade.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-092', 'enf', null, 'A menopausa é reconhecida após:', '["12 meses consecutivos de amenorreia.","3 meses sem menstruação.","o primeiro ciclo irregular.","6 meses de ciclos curtos.","a primeira onda de calor."]'::jsonb, 0, 'O climatério é a fase de transição do período reprodutivo para o não reprodutivo; a menopausa é a última menstruação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-093', 'enf', null, 'No atendimento à mulher vítima de violência sexual, a profilaxia antirretroviral (PEP) para HIV deve ser iniciada:', '["o mais precocemente possível, em até 72 horas após a exposição.","somente após 7 dias.","apenas se houver boletim de ocorrência.","somente após resultado positivo do agressor.","após 30 dias, se houver sintomas."]'::jsonb, 0, 'Também se oferecem anticoncepção de emergência, profilaxia de IST e de hepatite B, e notificação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-094', 'enf', null, 'Segundo a Lei nº 12.845/2013, o atendimento às pessoas em situação de violência sexual nos hospitais do SUS:', '["é obrigatório, emergencial e integral, não dependendo da apresentação de boletim de ocorrência.","depende de boletim de ocorrência prévio.","exige autorização judicial.","é restrito a mulheres maiores de 18 anos.","é opcional para hospitais conveniados."]'::jsonb, 0, 'A lei garante diagnóstico, tratamento das lesões, profilaxias e encaminhamentos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-095', 'enf', null, 'No Brasil, o aborto é permitido legalmente nos casos de:', '["risco de vida para a gestante, gravidez resultante de estupro e anencefalia fetal.","qualquer malformação fetal.","desejo da mulher até 12 semanas.","dificuldade financeira.","gravidez na adolescência."]'::jsonb, 0, 'Art. 128 do Código Penal e decisão do STF (ADPF 54) para anencefalia.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-096', 'enf', null, 'Segundo a Lei Maria da Penha, a retenção, subtração ou destruição de objetos, documentos pessoais, bens ou recursos econômicos da mulher configura violência:', '["patrimonial.","moral.","psicológica.","física.","sexual."]'::jsonb, 0, 'Violência moral: calúnia, difamação ou injúria. Psicológica: dano emocional, controle, humilhação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-097', 'enf', null, 'Quanto ao rastreamento do câncer de próstata, o Ministério da Saúde e o INCA:', '["não recomendam o rastreamento populacional com PSA em homens assintomáticos.","recomendam PSA anual para todos os homens a partir dos 30 anos.","recomendam toque retal semestral obrigatório.","recomendam biópsia de rotina aos 50 anos.","consideram o PSA dispensável mesmo em homens com sintomas."]'::jsonb, 0, 'Os danos (sobrediagnóstico e sobretratamento) superam os benefícios na população geral; a decisão deve ser compartilhada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-098', 'enf', null, 'O "pré-natal do parceiro", estratégia da PNAISH, consiste em:', '["inserir o parceiro nas consultas de pré-natal, oferecendo exames, testes rápidos, vacinação e atividades educativas.","realizar o pré-natal apenas pelo parceiro.","substituir as consultas da gestante.","acompanhar exclusivamente a saúde do bebê.","realizar ultrassonografia no parceiro."]'::jsonb, 0, 'Amplia o cuidado ao homem e estimula a paternidade ativa.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-099', 'enf', null, 'Os chamados "gigantes da geriatria" incluem:', '["incapacidade cognitiva, instabilidade postural, imobilidade, incontinência e iatrogenia.","hipertensão, diabetes, obesidade, tabagismo e alcoolismo.","gripe, pneumonia, diarreia, dengue e covid-19.","catarata, glaucoma, otite, rinite e sinusite.","anemia, desnutrição, sobrepeso, dislipidemia e gota."]'::jsonb, 0, 'Alguns autores acrescentam a insuficiência familiar.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-100', 'enf', null, 'Os critérios de Beers são utilizados para identificar, em idosos:', '["medicamentos potencialmente inapropriados.","risco de queda.","grau de dependência funcional.","estado nutricional.","depressão."]'::jsonb, 0, 'A polifarmácia e a iatrogenia são importantes causas de agravos na pessoa idosa.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-101', 'enf', null, 'A escala de Lawton avalia, na pessoa idosa:', '["as atividades instrumentais de vida diária, como usar o telefone, fazer compras e controlar finanças.","as atividades básicas de vida diária, como banho e alimentação.","o risco de lesão por pressão.","a função cognitiva.","o equilíbrio e a marcha."]'::jsonb, 0, 'Katz avalia as atividades básicas de vida diária.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-102', 'enf', null, 'O Mini-Exame do Estado Mental (MEEM) é um instrumento de rastreio:', '["cognitivo, cuja nota de corte varia conforme a escolaridade.","de depressão.","nutricional.","de risco de queda.","de dor."]'::jsonb, 0, 'Avalia orientação, memória, atenção, cálculo, linguagem e habilidade visuoespacial.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-103', 'enf', null, 'Segundo o Estatuto da Pessoa Idosa, os casos de suspeita ou confirmação de violência praticada contra pessoa idosa:', '["serão objeto de notificação compulsória pelos serviços de saúde públicos e privados.","só devem ser registrados com autorização da família.","são de notificação facultativa.","devem ser comunicados apenas ao cartório.","dispensam qualquer registro."]'::jsonb, 0, 'Art. 19, que também prevê comunicação à autoridade policial, ao Ministério Público e aos Conselhos da Pessoa Idosa.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-104', 'enf', null, 'Na Rede de Atenção Psicossocial, os Serviços Residenciais Terapêuticos (SRT) fazem parte do componente:', '["estratégias de desinstitucionalização.","atenção básica.","atenção de urgência e emergência.","atenção hospitalar.","reabilitação psicossocial apenas por cooperativas."]'::jsonb, 0, 'São moradias para egressos de longas internações psiquiátricas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-105', 'enf', null, 'O Programa De Volta para Casa (Lei nº 10.708/2003) consiste em:', '["auxílio-reabilitação psicossocial pago a egressos de longas internações psiquiátricas.","internação compulsória de usuários de drogas.","construção de hospitais psiquiátricos.","bolsa para estudantes de psicologia.","atendimento domiciliar para idosos."]'::jsonb, 0, 'Favorece a reinserção social e a autonomia.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-106', 'enf', null, 'A Unidade de Acolhimento (UA), na RAPS, oferece:', '["cuidado residencial transitório, por até 6 meses, a pessoas com necessidades decorrentes do uso de álcool e outras drogas.","internação de longa permanência.","atendimento ambulatorial de psiquiatria apenas.","leitos de UTI psiquiátrica.","atendimento exclusivo a crianças."]'::jsonb, 0, 'Funciona 24 horas, articulada ao CAPS de referência.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-107', 'enf', null, 'A estratégia de redução de danos, no cuidado a pessoas que usam álcool e outras drogas, tem como princípio:', '["reduzir os prejuízos à saúde e sociais do uso, sem exigir a abstinência como condição para o cuidado.","exigir abstinência imediata para iniciar o tratamento.","internar compulsoriamente todos os usuários.","punir o usuário pelo uso.","ofertar cuidado apenas a quem já parou de usar."]'::jsonb, 0, 'Respeita a autonomia e amplia o acesso ao cuidado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-108', 'enf', null, 'O Projeto Terapêutico Singular (PTS) é:', '["um conjunto de propostas de condutas terapêuticas articuladas, para um sujeito individual ou coletivo, resultante da discussão de uma equipe interdisciplinar.","a prescrição médica de psicofármacos.","um formulário de alta hospitalar.","o laudo de internação involuntária.","o plano de cargos e salários da unidade."]'::jsonb, 0, 'Etapas: diagnóstico, definição de metas, divisão de responsabilidades e reavaliação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-109', 'enf', null, 'O apoio matricial (matriciamento) em saúde mental consiste em:', '["suporte técnico-pedagógico de equipes especializadas às equipes de referência, como as da atenção básica, com corresponsabilização do cuidado.","transferência definitiva dos casos para o especialista.","fiscalização das equipes de atenção básica.","realização de internações psiquiátricas.","distribuição de medicamentos controlados."]'::jsonb, 0, 'Inclui discussão de casos, consultas conjuntas e educação permanente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-110', 'enf', null, 'É agravo relacionado ao trabalho de notificação compulsória no SINAN:', '["acidente de trabalho com exposição a material biológico.","resfriado comum em trabalhador.","lombalgia sem relação com o trabalho.","cárie dentária.","miopia."]'::jsonb, 0, 'Também são notificados acidentes de trabalho graves, fatais e com crianças e adolescentes, entre outros.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-111', 'enf', null, 'Segundo a Lei nº 8.213/1991, a Comunicação de Acidente de Trabalho (CAT) deve ser emitida pela empresa:', '["até o primeiro dia útil seguinte ao da ocorrência e, em caso de morte, de imediato.","em até 30 dias.","apenas se o trabalhador for afastado por mais de 15 dias.","somente quando houver óbito.","apenas a pedido do sindicato."]'::jsonb, 0, 'Na falta de emissão pela empresa, podem formalizá-la o próprio acidentado, seus dependentes, o sindicato, o médico ou autoridade pública.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-112', 'enf', null, 'Segundo a NR-32, deve ser fornecida gratuitamente aos trabalhadores dos serviços de saúde a vacinação contra:', '["tétano, difteria e hepatite B, além das estabelecidas no PCMSO.","febre amarela, apenas.","HPV e varicela, apenas.","dengue.","nenhuma, pois a vacinação é responsabilidade do trabalhador."]'::jsonb, 0, 'O empregador deve garantir o controle da eficácia da vacinação e o reforço quando necessário.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-113', 'enf', null, 'O programa que tem por objetivo a promoção e preservação da saúde dos trabalhadores, com exames médicos admissionais, periódicos e demissionais, é o:', '["Programa de Controle Médico de Saúde Ocupacional (PCMSO), previsto na NR-7.","Programa Nacional de Imunizações.","Programa Saúde na Escola.","Programa Mais Médicos.","Programa Farmácia Popular."]'::jsonb, 0, 'A NR-32 trata especificamente da segurança e saúde no trabalho em serviços de saúde.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-114', 'enf', null, 'O sistema de informação que tem como documento-base a Declaração de Nascido Vivo (DNV) é o:', '["SINASC.","SIM.","SINAN.","SIH/SUS.","SI-PNI."]'::jsonb, 0, 'SIM: Declaração de Óbito; SINAN: notificação de agravos; SIH: internações (AIH).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-115', 'enf', null, 'A Declaração de Óbito é o documento-base do:', '["Sistema de Informações sobre Mortalidade (SIM).","SINASC.","SINAN.","SISVAN.","e-SUS AB."]'::jsonb, 0, 'Também é o documento necessário para o registro civil do óbito.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-116', 'enf', null, 'A taxa de letalidade de uma doença expressa:', '["a proporção de óbitos entre os casos da doença.","o número de óbitos na população total.","o número de casos novos na população.","a proporção de vacinados.","o número de internações."]'::jsonb, 0, 'Letalidade = óbitos pela doença ÷ casos da doença × 100 (gravidade). Mortalidade usa a população como denominador.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-117', 'enf', null, 'Considera-se morte materna o óbito de uma mulher:', '["durante a gestação ou até 42 dias após o seu término, por causa relacionada ou agravada pela gravidez, não por causas acidentais ou incidentais.","até 1 ano após o parto, por qualquer causa.","somente durante o trabalho de parto.","apenas por hemorragia pós-parto.","durante a gestação, incluindo acidentes de trânsito."]'::jsonb, 0, 'Morte materna tardia: entre 42 dias e 1 ano após o término da gestação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-118', 'enf', null, 'A razão de mortalidade materna é expressa por:', '["100.000 nascidos vivos.","1.000 habitantes.","100 gestantes.","1.000 mulheres em idade fértil.","10.000 partos cesáreos."]'::jsonb, 0, 'Numerador: óbitos maternos; denominador: nascidos vivos, no mesmo local e período.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-119', 'enf', null, 'A ocorrência de casos de uma doença em número claramente acima do esperado, em determinada região e período, caracteriza:', '["epidemia.","endemia.","pandemia.","caso esporádico.","prevalência."]'::jsonb, 0, 'Endemia: ocorrência habitual, dentro do esperado. Pandemia: epidemia de ampla distribuição geográfica, atingindo vários países/continentes.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-120', 'enf', null, 'O valor preditivo positivo de um teste diagnóstico corresponde:', '["à probabilidade de uma pessoa com teste positivo realmente ter a doença.","à capacidade do teste de identificar os doentes.","à capacidade do teste de identificar os sadios.","ao custo do teste.","à reprodutibilidade do teste."]'::jsonb, 0, 'O VPP aumenta quando a prevalência da doença na população é maior.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-121', 'enf', null, 'O estudo epidemiológico que parte de um grupo de pessoas expostas e não expostas a um fator e as acompanha ao longo do tempo para observar o surgimento da doença é o:', '["estudo de coorte.","estudo de caso-controle.","estudo transversal.","relato de caso.","estudo ecológico."]'::jsonb, 0, 'No caso-controle, parte-se do desfecho (doentes e não doentes) e investiga-se a exposição passada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-122', 'enf', null, 'Segundo o modelo de Leavell e Clark, a vacinação é uma medida de prevenção:', '["primária (proteção específica).","secundária.","terciária.","quaternária.","de reabilitação."]'::jsonb, 0, 'Primária: promoção e proteção específica; secundária: diagnóstico precoce e tratamento; terciária: reabilitação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-123', 'enf', null, 'A prevenção quaternária refere-se a:', '["ações para evitar intervenções desnecessárias e a sobremedicalização, protegendo o paciente de danos iatrogênicos.","reabilitação de sequelas.","diagnóstico precoce de doenças.","vacinação de idosos.","promoção de atividade física."]'::jsonb, 0, 'Conceito associado ao princípio "primeiro, não causar dano".') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-124', 'enf', null, 'É agravo de notificação compulsória imediata (até 24 horas):', '["botulismo.","tuberculose.","hanseníase.","esquistossomose.","hepatite C."]'::jsonb, 0, 'Botulismo, cólera, raiva humana, sarampo e doença de Chagas aguda estão entre os agravos de notificação imediata.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-125', 'enf', null, 'A transição epidemiológica no Brasil caracteriza-se por:', '["redução da mortalidade por doenças infecciosas e aumento das doenças crônicas não transmissíveis e causas externas, com persistência de doenças infecciosas (tripla carga).","aumento exclusivo das doenças infecciosas.","desaparecimento completo das doenças transmissíveis.","redução das doenças cardiovasculares.","estabilidade do perfil de morbimortalidade desde 1950."]'::jsonb, 0, 'Está associada ao envelhecimento populacional e à urbanização.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-126', 'enf', null, 'Segundo as Diretrizes Brasileiras de Hipertensão Arterial (2020), o diagnóstico de hipertensão no consultório é feito com PA:', '["≥ 140 e/ou 90 mmHg, confirmada em pelo menos duas ocasiões (ou por MAPA/MRPA).","≥ 120/80 mmHg em uma única medida.","≥ 160/100 mmHg obrigatoriamente.","≥ 130/85 mmHg em uma medida.","apenas quando houver sintomas."]'::jsonb, 0, 'O diagnóstico não deve se basear em medida isolada, salvo em situações de PA muito elevada com lesão de órgão-alvo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-127', 'enf', null, 'O escore de Framingham é utilizado para estimar:', '["o risco cardiovascular em 10 anos.","o risco de queda.","o grau de desidratação.","a gravidade da sepse.","o risco de lesão por pressão."]'::jsonb, 0, 'Orienta a intensidade das intervenções em hipertensos, diabéticos e dislipidêmicos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-128', 'enf', null, 'No tratamento farmacológico do diabetes mellitus tipo 2, o medicamento de primeira escolha, na ausência de contraindicações, é:', '["metformina.","insulina NPH.","glibenclamida.","acarbose.","insulina regular."]'::jsonb, 0, 'A metformina não causa hipoglicemia quando usada isoladamente e pode reduzir peso.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-129', 'enf', null, 'São sintomas adrenérgicos (autonômicos) da hipoglicemia:', '["sudorese, tremores, taquicardia, palidez e fome.","poliúria e polidipsia.","hálito cetônico e respiração de Kussmaul.","febre e rigidez de nuca.","bradicardia e pele quente e seca."]'::jsonb, 0, 'Sintomas neuroglicopênicos: confusão, alteração de comportamento, convulsão e coma.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-130', 'enf', null, 'Segundo a OMS, a circunferência abdominal associada a risco MUITO aumentado de complicações metabólicas é de:', '["≥ 102 cm em homens e ≥ 88 cm em mulheres.","≥ 80 cm em homens e ≥ 70 cm em mulheres.","≥ 120 cm em ambos os sexos.","≥ 90 cm em homens e ≥ 100 cm em mulheres.","≥ 70 cm em ambos os sexos."]'::jsonb, 0, 'Risco aumentado: ≥ 94 cm (homens) e ≥ 80 cm (mulheres).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-131', 'enf', null, 'Segundo a OMS, em adultos, considera-se obesidade o índice de massa corporal (IMC):', '["≥ 30 kg/m².","≥ 25 kg/m².","≥ 18,5 kg/m².","≥ 40 kg/m², apenas.","≥ 22 kg/m²."]'::jsonb, 0, 'Sobrepeso: 25 a 29,9; obesidade grau I: 30–34,9; II: 35–39,9; III: ≥ 40.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-132', 'enf', null, 'No tratamento do tabagismo pelo SUS, a abordagem recomendada inclui:', '["abordagem cognitivo-comportamental, podendo ser associada a terapia de reposição de nicotina e/ou bupropiona.","internação compulsória.","apenas orientação para parar sozinho.","uso exclusivo de ansiolíticos.","redução gradual sem acompanhamento."]'::jsonb, 0, 'O Programa Nacional de Controle do Tabagismo oferece tratamento gratuito nas unidades de saúde.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-133', 'enf', null, 'A vacina BCG deve ser adiada em recém-nascidos:', '["com peso inferior a 2.000 g.","com icterícia fisiológica.","filhos de mãe com hepatite B.","nascidos de parto cesáreo.","que ainda não receberam a vacina hepatite B."]'::jsonb, 0, 'Também é contraindicada em imunodeficiências e em RN expostos ao HIV sintomáticos, conforme protocolo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-134', 'enf', null, 'Na profilaxia da raiva humana, a lambedura de mucosas por cão ou gato é classificada como:', '["acidente grave.","acidente leve.","contato indireto, sem risco.","não exposição.","acidente moderado sem indicação de profilaxia."]'::jsonb, 0, 'Também são graves ferimentos na cabeça, face, pescoço, mãos, pés, ferimentos profundos ou múltiplos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-135', 'enf', null, 'O recém-nascido de mãe HBsAg reagente deve receber:', '["vacina hepatite B e imunoglobulina humana anti-hepatite B, preferencialmente nas primeiras 12 a 24 horas de vida.","apenas a vacina aos 2 meses.","apenas a imunoglobulina após 30 dias.","nenhuma medida, se nascer de cesárea.","suspensão definitiva do aleitamento materno."]'::jsonb, 0, 'Com a imunoprofilaxia adequada, a amamentação não é contraindicada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-136', 'enf', null, 'Os eventos supostamente atribuíveis à vacinação ou imunização (ESAVI) graves devem ser notificados em até:', '["24 horas.","7 dias.","30 dias.","6 meses.","não precisam ser notificados."]'::jsonb, 0, 'Os ESAVI graves são de notificação imediata e devem ser investigados.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-137', 'enf', null, 'Para adulto sem comprovação de vacinação contra difteria e tétano, o esquema recomendado com a dT é:', '["três doses, com intervalo de 60 dias entre elas (mínimo de 30 dias).","dose única.","duas doses com intervalo de 1 ano.","cinco doses mensais.","uma dose a cada ano."]'::jsonb, 0, 'Depois, reforço a cada 10 anos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-138', 'enf', null, 'Segundo o PNI, a vacina HPV para pessoas imunossuprimidas (por exemplo, vivendo com HIV, transplantadas ou em tratamento oncológico) é indicada na faixa etária de:', '["9 a 45 anos, em esquema de 3 doses.","9 a 14 anos, em dose única.","acima de 60 anos.","apenas meninas de 9 anos.","é contraindicada nesses grupos."]'::jsonb, 0, 'Para a população geral de 9 a 14 anos, o esquema é de dose única.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-139', 'enf', null, 'A vigilância sanitária exerce suas ações com base no:', '["poder de polícia administrativa, podendo fiscalizar, interditar e aplicar penalidades.","poder judiciário.","poder legislativo municipal.","contrato privado com os estabelecimentos.","consentimento prévio dos fiscalizados."]'::jsonb, 0, 'O poder de polícia limita direitos individuais em benefício do interesse público.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-140', 'enf', null, 'A RDC ANVISA nº 36/2013 determina que os serviços de saúde devem:', '["constituir Núcleo de Segurança do Paciente (NSP) e elaborar o Plano de Segurança do Paciente.","extinguir a CCIH.","dispensar a notificação de eventos adversos.","terceirizar a farmácia hospitalar.","adotar prontuário exclusivamente em papel."]'::jsonb, 0, 'Os eventos adversos devem ser notificados ao Sistema Nacional de Vigilância Sanitária.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-141', 'enf', null, 'O sistema da ANVISA utilizado para notificação de eventos adversos e queixas técnicas relacionados a produtos e serviços de saúde é o:', '["NOTIVISA.","SINAN.","SIM.","SINASC.","SISREG."]'::jsonb, 0, 'Abrange farmacovigilância, tecnovigilância, hemovigilância, cosmetovigilância e eventos assistenciais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-142', 'enf', null, 'A área da vigilância que monitora eventos adversos e queixas técnicas relacionados a equipamentos e produtos para saúde (exceto medicamentos) é a:', '["tecnovigilância.","farmacovigilância.","hemovigilância.","vigilância epidemiológica.","vigilância ambiental."]'::jsonb, 0, 'Farmacovigilância: medicamentos; hemovigilância: sangue e hemocomponentes.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-143', 'enf', null, 'Segundo o Sepsis-3, o qSOFA (quick SOFA), usado à beira do leito para identificar pacientes com suspeita de infecção e maior risco de desfecho desfavorável, considera:', '["frequência respiratória ≥ 22 irpm, alteração do estado mental e PAS ≤ 100 mmHg.","temperatura, leucocitose e glicemia.","diurese, creatinina e bilirrubina.","frequência cardíaca, lactato e plaquetas.","saturação, idade e sexo."]'::jsonb, 0, 'Dois ou mais critérios indicam maior risco, mas a ausência não exclui sepse.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-144', 'enf', null, 'O pacote da primeira hora no atendimento ao paciente com sepse/choque séptico inclui:', '["dosar lactato, colher hemoculturas antes do antibiótico, iniciar antibiótico de amplo espectro, infundir cristaloide (30 mL/kg) se hipotensão ou lactato ≥ 4 e iniciar vasopressor se PAM < 65 mmHg após volume.","aguardar resultado de culturas para iniciar o antibiótico.","restringir líquidos em todos os casos.","iniciar corticoide e aguardar 6 horas.","administrar antitérmico e reavaliar no dia seguinte."]'::jsonb, 0, 'Cada hora de atraso no antibiótico aumenta a mortalidade.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-145', 'enf', null, 'Um paciente apresenta PA de 120 x 60 mmHg. A pressão arterial média (PAM) é de aproximadamente:', '["80 mmHg.","90 mmHg.","60 mmHg.","100 mmHg.","70 mmHg."]'::jsonb, 0, 'PAM = (PAS + 2 × PAD) ÷ 3 = (120 + 120) ÷ 3 = 80 mmHg.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-146', 'enf', null, 'Gasometria arterial: pH 7,25; PaCO2 60 mmHg; HCO3- 26 mEq/L. A interpretação é:', '["acidose respiratória.","acidose metabólica.","alcalose respiratória.","alcalose metabólica.","gasometria normal."]'::jsonb, 0, 'pH baixo (< 7,35) com PaCO2 alta (> 45) e bicarbonato normal: acidose respiratória (por hipoventilação).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-147', 'enf', null, 'Gasometria arterial: pH 7,28; PaCO2 30 mmHg; HCO3- 14 mEq/L. A interpretação é:', '["acidose metabólica com compensação respiratória.","acidose respiratória.","alcalose metabólica.","alcalose respiratória.","gasometria normal."]'::jsonb, 0, 'pH baixo com bicarbonato baixo = acidose metabólica; a PaCO2 baixa indica hiperventilação compensatória.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-148', 'enf', null, 'Paciente com taquicardia, pulso presente e sinais de instabilidade (hipotensão, rebaixamento de consciência, dor torácica isquêmica). A conduta indicada é:', '["cardioversão elétrica sincronizada.","desfibrilação não sincronizada.","massagem do seio carotídeo apenas.","observação por 2 horas.","administração de atropina."]'::jsonb, 0, 'Em pacientes estáveis, avaliam-se manobras vagais e antiarrítmicos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-149', 'enf', null, 'Na bradicardia sintomática em adulto, o fármaco inicial recomendado é:', '["atropina 1 mg EV, podendo repetir a cada 3 a 5 minutos até dose máxima de 3 mg.","adenosina 6 mg.","amiodarona 300 mg.","adrenalina 1 mg em bolus a cada 3 minutos.","furosemida 40 mg."]'::jsonb, 0, 'Se ineficaz: marca-passo transcutâneo ou infusão de dopamina/adrenalina.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-150', 'enf', null, 'Na hipercalemia grave com alterações no eletrocardiograma (como ondas T apiculadas), o medicamento usado para estabilizar a membrana do miocárdio é o:', '["gluconato de cálcio.","cloreto de potássio.","bicarbonato de sódio em todos os casos.","digoxina.","sulfato de magnésio."]'::jsonb, 0, 'Insulina com glicose, beta-2 agonistas e diuréticos ajudam a reduzir o potássio sérico.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-151', 'enf', null, 'No edema agudo de pulmão cardiogênico, as condutas iniciais incluem:', '["manter o paciente sentado, oferecer oxigênio/ventilação não invasiva e administrar diurético e vasodilatador conforme prescrição.","colocar o paciente em Trendelenburg.","infundir grande volume de soro rapidamente.","restringir oxigênio.","administrar betabloqueador em bolus."]'::jsonb, 0, 'A posição sentada com pernas pendentes reduz o retorno venoso.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-152', 'enf', null, 'No traumatismo cranioencefálico com hipertensão intracraniana grave, a tríade de Cushing é composta por:', '["hipertensão arterial, bradicardia e alterações do padrão respiratório.","hipotensão, taquicardia e febre.","hipoglicemia, sudorese e tremores.","febre, rigidez de nuca e petéquias.","taquipneia, taquicardia e hipotermia."]'::jsonb, 0, 'É um sinal tardio, que indica risco de herniação cerebral.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-153', 'enf', null, 'Na Escala de Coma de Glasgow com resposta pupilar (ECG-P), quando nenhuma das pupilas reage à luz:', '["subtraem-se 2 pontos do escore total de Glasgow.","somam-se 2 pontos ao escore.","o escore passa a ser 15.","subtrai-se 1 ponto.","a avaliação pupilar não altera o escore."]'::jsonb, 0, 'Uma pupila sem reação: −1; ambas sem reação: −2. O ECG-P pode variar de 1 a 15.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-154', 'enf', null, 'Pela fórmula de Parkland, um adulto de 70 kg com 20% de superfície corporal queimada (2º e 3º graus) deve receber nas primeiras 24 horas:', '["5.600 mL de Ringer lactato, sendo metade nas primeiras 8 horas.","2.800 mL em 24 horas, de forma igual.","1.400 mL nas primeiras 8 horas.","14.000 mL nas primeiras 8 horas.","560 mL em 24 horas."]'::jsonb, 0, '4 mL × 70 kg × 20% = 5.600 mL; 2.800 mL nas primeiras 8 h (contadas a partir da queimadura) e 2.800 mL nas 16 h seguintes.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-155', 'enf', null, 'Na anafilaxia em adulto, a dose recomendada de adrenalina por via intramuscular é de:', '["0,5 mg (0,01 mg/kg, máximo de 0,5 mg), podendo repetir a cada 5 a 15 minutos.","1 mg EV em bolus como primeira escolha.","5 mg IM.","0,05 mg SC.","10 mg IM."]'::jsonb, 0, 'A via EV em bolus é reservada a situações de PCR ou choque refratário com monitorização.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-156', 'enf', null, 'O instrumento utilizado para detectar delirium em pacientes de UTI, inclusive em ventilação mecânica, é o:', '["CAM-ICU.","RASS.","Braden.","APACHE II.","Glasgow."]'::jsonb, 0, 'O RASS avalia sedação/agitação e é pré-requisito para aplicar o CAM-ICU.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-157', 'enf', null, 'Para avaliação da dor em pacientes sedados e em ventilação mecânica, incapazes de se comunicar, utiliza-se a escala:', '["comportamental de dor (BPS - Behavioral Pain Scale).","numérica de 0 a 10.","de faces.","de Morse.","de Fugulin."]'::jsonb, 0, 'Avalia expressão facial, movimentos dos membros superiores e adaptação ao ventilador.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-158', 'enf', null, 'No choque séptico, a noradrenalina:', '["é o vasopressor de primeira escolha e deve ser infundida em bomba, preferencialmente por acesso venoso central.","deve ser administrada em bolus por via periférica.","é contraindicada.","deve ser diluída em água e dada por via oral.","é usada apenas para tratar bradicardia."]'::jsonb, 0, 'Meta usual: PAM ≥ 65 mmHg. Monitorar sinais de extravasamento e isquemia periférica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-159', 'enf', null, 'Segundo a Resolução CFM nº 2.173/2017 e a legislação de transplantes, diante da suspeita de morte encefálica, é obrigatório:', '["notificar a Central Estadual de Transplantes, sendo a morte encefálica de notificação compulsória.","aguardar autorização da família para iniciar o protocolo.","suspender todos os cuidados imediatamente.","realizar apenas um exame clínico.","dispensar exame complementar em adultos."]'::jsonb, 0, 'O protocolo inclui dois exames clínicos por médicos diferentes, teste de apneia e exame complementar.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-160', 'enf', null, 'A esterilização por plasma de peróxido de hidrogênio é indicada para:', '["materiais termossensíveis, sendo incompatível com celulose (papel, algodão, tecidos).","todos os tecidos de algodão.","líquidos e pós.","materiais que suportam alta temperatura apenas.","embalagens de papel grau cirúrgico."]'::jsonb, 0, 'Processo de baixa temperatura, sem resíduos tóxicos; usa embalagens de Tyvek®.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-161', 'enf', null, 'Uma desvantagem da esterilização por óxido de etileno é:', '["a toxicidade do gás, que exige aeração dos materiais antes do uso.","a alta temperatura, que danifica plásticos.","o baixo custo, que reduz a qualidade.","a incapacidade de esterilizar materiais termossensíveis.","a necessidade de água destilada no processo."]'::jsonb, 0, 'O gás é tóxico, mutagênico e carcinogênico; exige controle ocupacional rigoroso.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-162', 'enf', null, 'A limpeza de instrumentais em lavadora ultrassônica ocorre principalmente por:', '["cavitação, que remove sujidades de locais de difícil acesso.","esterilização a vapor.","radiação ionizante.","desinfecção química de alto nível.","fricção manual com escova."]'::jsonb, 0, 'Ondas sonoras formam microbolhas que implodem e desprendem a sujidade.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-163', 'enf', null, 'Segundo a RDC nº 15/2012, o monitoramento do processo de esterilização a vapor com indicador biológico deve ser feito:', '["no mínimo diariamente, em pacote desafio, e em todas as cargas com produtos implantáveis.","uma vez por mês.","uma vez por ano, na manutenção.","apenas quando houver suspeita de falha.","somente em autoclaves novas."]'::jsonb, 0, 'Cargas com implantáveis só devem ser liberadas após a leitura do indicador biológico.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-164', 'enf', null, 'Para a prevenção da infecção do trato urinário associada a cateter vesical, a medida mais efetiva é:', '["evitar o uso desnecessário e remover o cateter o mais precocemente possível.","trocar o cateter a cada 24 horas.","irrigar a sonda rotineiramente.","manter a bolsa acima do nível da bexiga.","usar antibiótico profilático contínuo."]'::jsonb, 0, 'A duração da cateterização é o principal fator de risco.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-165', 'enf', null, 'Para a prevenção de infecção do sítio cirúrgico, a antibioticoprofilaxia, quando indicada, deve ser administrada:', '["até 60 minutos antes da incisão cirúrgica.","24 horas antes da cirurgia.","somente após o término da cirurgia.","por 10 dias após a alta.","no momento da sutura da pele."]'::jsonb, 0, 'O objetivo é obter nível tecidual adequado no momento da incisão.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-166', 'enf', null, 'A sigla KPC refere-se a:', '["Klebsiella pneumoniae produtora de carbapenemase, bactéria multirresistente.","um tipo de vírus respiratório.","um antisséptico à base de clorexidina.","uma vacina contra pneumonia.","um teste de esterilização."]'::jsonb, 0, 'Exige precaução de contato e medidas rigorosas de controle de infecção.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-167', 'enf', null, 'A densidade de incidência de infecção primária de corrente sanguínea associada a cateter central é calculada:', '["pelo número de infecções dividido pelo número de cateteres-dia, multiplicado por 1.000.","pelo número de infecções dividido pelo número de leitos, multiplicado por 100.","pelo número de óbitos dividido pelo número de infecções.","pelo número de cateteres dividido pelo número de pacientes.","pelo número de culturas positivas no ano."]'::jsonb, 0, 'O uso de cateteres-dia como denominador considera o tempo de exposição.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-168', 'enf', null, 'Uma solução contém 4 mg de noradrenalina em 250 mL de soro glicosado. A concentração da solução é de:', '["16 mcg/mL.","4 mcg/mL.","62,5 mcg/mL.","1,6 mcg/mL.","160 mcg/mL."]'::jsonb, 0, '4 mg = 4.000 mcg; 4.000 ÷ 250 = 16 mcg/mL.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-169', 'enf', null, 'Dobutamina 250 mg diluída em 250 mL (1 mg/mL). Prescrição: 5 mcg/kg/min para paciente de 70 kg. A vazão na bomba de infusão será de:', '["21 mL/h.","5 mL/h.","35 mL/h.","350 mL/h.","2,1 mL/h."]'::jsonb, 0, '5 × 70 = 350 mcg/min × 60 = 21.000 mcg/h = 21 mg/h → 21 mL/h.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-170', 'enf', null, 'Medicamentos com nomes ou embalagens semelhantes, que favorecem trocas e erros, são chamados de:', '["LASA (look-alike, sound-alike).","MAV (medicamentos de alta vigilância).","MIP (medicamentos isentos de prescrição).","genéricos.","fitoterápicos."]'::jsonb, 0, 'Estratégias: armazenamento separado, etiquetas de alerta e letras maiúsculas destacadas (tall man lettering).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-171', 'enf', null, 'O sistema de distribuição de medicamentos considerado mais seguro, por reduzir erros e desperdícios, é o:', '["sistema de dose unitária.","sistema coletivo.","sistema individualizado por 5 dias.","estoque livre nas unidades.","sistema de pedido verbal."]'::jsonb, 0, 'O medicamento chega pronto para administração, identificado por paciente e horário.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-172', 'enf', null, 'Os frascos de insulina ainda não abertos devem ser armazenados:', '["sob refrigeração entre 2 °C e 8 °C, sem congelar.","no congelador.","em temperatura ambiente, expostos ao sol.","dentro do porta-luvas do carro.","em qualquer local, pois a insulina não altera."]'::jsonb, 0, 'Após aberta, pode ser mantida em temperatura ambiente (até cerca de 30 °C) pelo prazo indicado pelo fabricante.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-173', 'enf', null, 'A morfina, segundo a Portaria SVS/MS nº 344/1998, é classificada na lista A1 (entorpecentes), e sua prescrição exige:', '["Notificação de Receita A (cor amarela).","receita comum, sem retenção.","Notificação de Receita B (cor azul).","receita de controle especial em duas vias, de cor branca, apenas.","nenhuma receita."]'::jsonb, 0, 'Lista B1 (psicotrópicos, como benzodiazepínicos): Notificação de Receita B (azul).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-174', 'enf', null, 'O curativo de hidrocoloide é indicado para feridas:', '["com pouco a moderado exsudato e sem infecção, podendo permanecer até 7 dias.","infectadas e muito exsudativas.","com exposição óssea.","com necrose seca extensa, em substituição ao desbridamento cirúrgico.","com sangramento ativo."]'::jsonb, 0, 'Forma gel em contato com o exsudato, mantendo o meio úmido; é contraindicado em feridas infectadas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-175', 'enf', null, 'No uso da papaína em feridas, a concentração geralmente recomendada para tecido necrótico é de:', '["10%.","1%.","2%.","4%.","0,5%."]'::jsonb, 0, 'Usualmente: 2% em tecido de granulação; 4–6% em exsudato purulento/esfacelo; 10% em necrose.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-176', 'enf', null, 'O curativo de carvão ativado com prata é indicado principalmente para feridas:', '["infectadas, exsudativas e com odor.","limpas e secas.","em fase de epitelização.","com exposição de tendão sem exsudato.","de queimadura de 1º grau."]'::jsonb, 0, 'O carvão absorve o odor e a prata tem ação antimicrobiana.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-177', 'enf', null, 'A terapia por pressão negativa (TPN) em feridas tem como benefícios:', '["remoção de exsudato, redução do edema e estímulo à formação de tecido de granulação.","desbridamento enzimático de necrose seca.","tratamento de feridas com malignidade no leito.","substituição do controle de infecção.","indicação em sangramento ativo."]'::jsonb, 0, 'Contraindicações incluem malignidade no leito, necrose não desbridada e osteomielite não tratada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-178', 'enf', null, 'No tratamento da úlcera venosa de perna, a principal medida terapêutica é:', '["a terapia compressiva (como a bota de Unna), após excluir insuficiência arterial pelo índice tornozelo-braço.","manter a perna pendente o dia todo.","aplicar calor local intenso.","evitar a deambulação.","usar garrote abaixo do joelho."]'::jsonb, 0, 'A elevação dos membros também é recomendada; compressão em doença arterial pode causar isquemia.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-179', 'enf', null, 'É característica da úlcera arterial:', '["dor que piora com a elevação do membro, pulsos diminuídos ou ausentes e bordas regulares, com leito pálido.","edema e dermatite ocre ao redor.","localização típica no maléolo medial com muito exsudato.","dor que piora com o membro pendente.","pulsos amplos e pele quente."]'::jsonb, 0, 'A úlcera venosa é que se localiza tipicamente no maléolo medial, com edema e hiperpigmentação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-180', 'enf', null, 'A lesão por pressão tissular profunda é descrita como:', '["pele intacta ou não, com área localizada e persistente de coloração vermelho-escura, marrom ou púrpura que não embranquece, ou separação epidérmica com leito escuro ou bolha de sangue.","eritema que embranquece à digitopressão.","perda parcial da pele com exposição da derme.","perda total da pele com gordura visível.","lesão coberta por esfacelo que impede ver a profundidade."]'::jsonb, 0, 'Resulta de pressão e cisalhamento intensos na interface osso-músculo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-181', 'enf', null, 'No pós-operatório de confecção de estomia intestinal, um estoma de coloração escura (arroxeada ou preta) sugere:', '["necrose, devendo ser comunicada imediatamente.","evolução normal.","excesso de cuidados com a pele.","hidratação adequada.","estoma bem vascularizado."]'::jsonb, 0, 'O estoma saudável é vermelho vivo, úmido e brilhante.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-182', 'enf', null, 'A irrigação de colostomia, como método de controle intestinal, é indicada para pacientes com colostomia:', '["no cólon descendente ou sigmoide, com fezes formadas.","em ileostomia.","em urostomia.","no cólon ascendente com fezes líquidas.","em qualquer estoma, desde o 1º dia de pós-operatório."]'::jsonb, 0, 'Requer orientação do enfermeiro estomaterapeuta e avaliação médica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
